from __future__ import annotations

import datetime as dt
import secrets

from django.db import models
from django.utils import timezone


def _new_token() -> str:
    """Return a 22-character, URL-safe random token for a lecture's QR code."""
    return secrets.token_urlsafe(16)


# ===========================================================================
#  Abstract base
# ===========================================================================

class Timestamped(models.Model):
    """Abstract mixin that records when a row was created and last changed.

    Attributes:
        created: Set once, when the row is first saved.
        modified: Refreshed on every save.
    """

    created = models.DateTimeField(auto_now_add=True)
    modified = models.DateTimeField(auto_now=True)

    class Meta:
        abstract = True


class Person(Timestamped):
    """Abstract base shared by both profile types.

    Keeping instructors and students in separate concrete tables lets foreign
    keys enforce roles at the schema level (a Course can only reference an
    instructor), while this base avoids repeating the common columns.

    Attributes:
        university_id: Campus ID, unique within each table.
        first_name: Given name.
        last_name: Family name.
        email: Contact address, unique within each table.
    """

    university_id = models.CharField("university ID", max_length=13, unique=True)
    first_name = models.CharField(max_length=60)
    last_name = models.CharField(max_length=60)
    email = models.EmailField(unique=True)

    class Meta:
        abstract = True
        ordering = ("last_name", "first_name")

    @property
    def full_name(self) -> str:
        return f"{self.first_name} {self.last_name}"

    def __str__(self) -> str:
        return f"{self.last_name}, {self.first_name}"


# ===========================================================================
#  People
# ===========================================================================

class InstructorProfile(Person):
    """Faculty member. Owns zero or more ``Course`` rows via ``courses``."""

    department = models.CharField(max_length=80, blank=True)

    class Meta(Person.Meta):
        verbose_name = "instructor"


class StudentProfile(Person):
    """Learner. Reaches courses through ``Enrollment``.

    Attributes:
        graduation_year: Expected year of graduation, optional.
    """

    graduation_year = models.PositiveSmallIntegerField(null=True, blank=True)

    class Meta(Person.Meta):
        verbose_name = "student"

    def attendance_rate(self, course: Course) -> float:
        """Fraction (0.0-1.0) of a course's past lectures this student attended."""
        held = course.lectures.filter(date__lte=timezone.localdate())
        total = held.count()
        if not total:
            return 0.0
        attended = held.filter(scans__student=self).distinct().count()
        return attended / total


# ===========================================================================
#  Courses & schedule
# ===========================================================================

class Weekday(models.IntegerChoices):
    """ISO-style weekday numbers, aligned with ``date.weekday()``."""

    MONDAY = 0, "Mon"
    TUESDAY = 1, "Tue"
    WEDNESDAY = 2, "Wed"
    THURSDAY = 3, "Thu"
    FRIDAY = 4, "Fri"
    SATURDAY = 5, "Sat"
    SUNDAY = 6, "Sun"


class Course(Timestamped):
    """A catalog offering taught by a single instructor.

    The weekly schedule is stored as two columns: a comma-separated list of
    weekday numbers and a start/end time window.

    Attributes:
        title: Human-readable course name.
        catalog_number: Registrar identifier, e.g. ``"CMSC 13600"``.
        term: Free-text term label, e.g. ``"Autumn 2026"``.
        instructor: Teaching faculty; ``PROTECT`` blocks deleting an
            instructor who still has courses.
        weekdays: Comma-separated ``Weekday`` values, e.g. ``"0,2,4"``.
        starts_at: Local start time for every meeting.
        ends_at: Local end time for every meeting.
    """

    title = models.CharField(max_length=150)
    catalog_number = models.CharField(max_length=20)
    term = models.CharField(max_length=30)
    instructor = models.ForeignKey(
        InstructorProfile, on_delete=models.PROTECT, related_name="courses"
    )
    weekdays = models.CharField(max_length=13, help_text='e.g. "0,2,4" for Mon/Wed/Fri')
    starts_at = models.TimeField()
    ends_at = models.TimeField()

    class Meta:
        unique_together = ("catalog_number", "term")

    def __str__(self) -> str:
        return f"{self.catalog_number} ({self.term})"

    def clean(self) -> None:
        from django.core.exceptions import ValidationError
        if self.starts_at and self.ends_at and self.ends_at <= self.starts_at:
            raise ValidationError("A course must end after it starts.")

    @property
    def meeting_days(self) -> list[Weekday]:
        return [Weekday(int(d)) for d in self.weekdays.split(",") if d.strip()]

    @property
    def schedule_label(self) -> str:
        days = "/".join(d.label for d in self.meeting_days)
        return f"{days} {self.starts_at:%H:%M}–{self.ends_at:%H:%M}"

    def is_meeting_day(self, when: dt.date) -> bool:
        return Weekday(when.weekday()) in self.meeting_days


# ===========================================================================
#  Enrollment (explicit M2M)
# ===========================================================================

class EnrollmentQuerySet(models.QuerySet):
    def active(self) -> EnrollmentQuerySet:
        return self.filter(dropped_on__isnull=True)


class Enrollment(Timestamped):
    """Association row between ``StudentProfile`` and ``Course``.

    Dropping a course is recorded with ``dropped_on`` instead of deleting the
    row, so attendance history survives.

    Attributes:
        student: The enrolled learner.
        course: The course enrolled in.
        dropped_on: Date the student withdrew; ``None`` while active.
    """

    student = models.ForeignKey(StudentProfile, on_delete=models.CASCADE, related_name="enrollments")
    course = models.ForeignKey(Course, on_delete=models.CASCADE, related_name="enrollments")
    dropped_on = models.DateField(null=True, blank=True)

    objects = EnrollmentQuerySet.as_manager()

    class Meta:
        unique_together = ("student", "course")

    def __str__(self) -> str:
        return f"{self.student} → {self.course}"

    @property
    def is_active(self) -> bool:
        return self.dropped_on is None


# ===========================================================================
#  Lectures & QR scans
# ===========================================================================

class Lecture(Timestamped):
    """A single class session; its ``token`` is what the QR image encodes.

    Attributes:
        course: Parent course.
        held_on: Calendar date of the session.
        token: Random URL-safe string, regenerated with ``rotate_token()``.
    """

    course = models.ForeignKey(Course, on_delete=models.CASCADE, related_name="lectures")
    held_on = models.DateField("date")
    token = models.CharField(max_length=32, unique=True, default=_new_token, editable=False)

    class Meta:
        get_latest_by = "held_on"
        ordering = ("-held_on",)

    def __str__(self) -> str:
        return f"{self.course.catalog_number} · {self.held_on:%b %d, %Y}"

    @property
    def date(self) -> dt.date:
        return self.held_on

    def rotate_token(self) -> str:
        """Issue a fresh QR token (e.g. if the old one leaked) and save."""
        self.token = _new_token()
        self.save(update_fields=["token", "modified"])
        return self.token


class ScanStatus(models.TextChoices):
    PENDING = "pending", "Awaiting match"
    ACCEPTED = "accepted", "Accepted"
    REJECTED = "rejected", "Rejected"


class QRCodeUpload(Timestamped):
    """An image a student submitted as proof of presence.

    ``lecture`` stays empty until the decoded token is matched; ``status``
    tracks the review outcome.

    Attributes:
        student: Who submitted the image.
        lecture: Matched session, if any.
        image: The uploaded picture.
        status: One of ``ScanStatus``.
    """

    student = models.ForeignKey(StudentProfile, on_delete=models.CASCADE, related_name="scans")
    lecture = models.ForeignKey(
        Lecture, on_delete=models.SET_NULL, null=True, blank=True, related_name="scans"
    )
    image = models.FileField(upload_to="scans/%Y/%m/%d/")
    status = models.CharField(max_length=10, choices=ScanStatus.choices, default=ScanStatus.PENDING)

    class Meta:
        verbose_name = "QR code upload"
        indexes = [models.Index(fields=("lecture", "student"))]

    def __str__(self) -> str:
        return f"scan #{self.pk} [{self.get_status_display()}]"

    def match(self, token: str) -> bool:
        """Link this upload to the lecture whose token matches.

        Returns ``True`` and marks the scan accepted when a lecture is found;
        otherwise marks it rejected and returns ``False``.
        """
        self.lecture = Lecture.objects.filter(token=token).first()
        self.status = ScanStatus.ACCEPTED if self.lecture else ScanStatus.REJECTED
        self.save(update_fields=["lecture", "status", "modified"])
        return self.lecture is not None
